wps = {}
for i in range(12):
    name = f"waypoint{i}"
    res = primitives.call(name="ground_rlbench_target", target_name=name)
    if res.ok:
        pe = res.output.get("pose_evidence", {})
        if pe.get("source") == "pyrep_object_pose":
            wps[name] = pe.get("pose_world")
            print(f"{name}:", [round(x, 5) for x in wps[name]])

# Let's move to waypoint0, waypoint1, close gripper, move to waypoint2, open gripper, move to waypoint3
for step_name, wp_key, grip_cmd in [
    ("move_wp0", "waypoint0", None),
    ("move_wp1", "waypoint1", "close"),
    ("move_wp2", "waypoint2", "open"),
    ("move_wp3", "waypoint3", None),
]:
    if wp_key in wps:
        m_res = primitives.call(name="move_rlbench_arm_to", target_name=wp_key, target_pose=wps[wp_key])
        print(step_name, "ok:", m_res.ok)
        if m_res.ok:
            st = m_res.output.get("data", {}).get("observation_summary", {}).get("state_fields", {})
            print("  gripper_pose:", [round(x, 4) for x in st.get("gripper_pose", [])])
        if grip_cmd == "close":
            c_res = primitives.call(name="close_rlbench_gripper")
            print("  close ok:", c_res.ok)
        elif grip_cmd == "open":
            o_res = primitives.call(name="open_rlbench_gripper")
            print("  open ok:", o_res.ok)

# Check updated cup and waypoint poses after opening door
for name in ["cup", "waypoint4", "waypoint5", "waypoint6"]:
    res = primitives.call(name="ground_rlbench_target", target_name=name)
    if res.ok:
        pe = res.output.get("pose_evidence", {})
        print(f"post-door {name}:", [round(x, 5) for x in pe.get("pose_world", [])])

print("m_res output:", m_res.output)
obs_now = primitives.call(name="observe_rlbench_scene", include_raw=False)
if obs_now.ok:
    st = obs_now.output.get("data", {}).get("observation_summary", {}).get("state_fields", {})
    print("current gripper_pose:", st.get("gripper_pose"))
    print("current gripper_open:", st.get("gripper_open"))

for name in ["waypoint0", "waypoint1", "waypoint2", "waypoint3"]:
    res = primitives.call(name="ground_rlbench_target", target_name=name)
    if res.ok:
        print(f"current {name}:", [round(x, 5) for x in res.output.get("pose_evidence", {}).get("pose_world", [])])
